// Parseert een DEGIRO-transactiebevestiging naar een transactie voor de website.
// Geeft { recognized: false, ... } terug als de mail geen orderbevestiging is
// (bv. een stortingsmail) — die mail breekt de flow dan niet, maar gaat naar de
// foutmelding-tak.
//
// n8n's Gmail Trigger levert de mailbody als platte tekst (geen tabel, geen
// "|"-tekens): DEGIRO's labels en waarden staan achter elkaar, met willekeurige
// regelafbrekingen halverwege een waarde, bv.:
//   "OrderID 18cff972-... Transactiedatum 28 sep 2026,\n15:30:02 ISIN KYG722451229
//    Opdracht Koop Type Limit Order Beurs NDQ Handelsplaats XNAS Aantal 17 ..."
// We zoeken daarom de positie van elk bekend label in de (whitespace-genormaliseerde)
// tekst, sorteren op positie, en de waarde van een label is alles tot het volgende
// gevonden label. Dat werkt ongeacht volgorde-afwijkingen of ontbrekende velden.

const MONTHS = {
  jan: '01', feb: '02', mrt: '03', apr: '04', mei: '05', jun: '06',
  jul: '07', aug: '08', sep: '09', okt: '10', nov: '11', dec: '12',
};

const STOPWORDS = new Set([
  'ltd', 'plc', 'nv', 'n.v.', 'inc', 'sa', 'ag', 'se', 'class', 'a', 'b',
  'etf', 'ucits', 'dist', 'acc', 'accumulating', 'core', '-', '(usd)', '(eur)',
]);

function deriveTicker(name) {
  const words = name.split(/\s+/).filter((w) => w && !STOPWORDS.has(w.toLowerCase().replace(/[.,]/g, '')));
  const base = (words[0] || name.replace(/[^A-Za-z]/g, '')).toUpperCase();
  return base.slice(0, 6);
}

const LABELS = [
  'OrderID', 'Transactiedatum', 'ISIN', 'Opdracht', 'Type', 'Beurs', 'Handelsplaats',
  'Aantal', 'Koers', 'Lokale waarde', 'Waarde', 'Wisselkoers', 'AutoFX kosten',
  'Transactiekosten en/of kosten van derden', 'Totale Kosten', 'Totaal',
];

function extractFields(rawBody) {
  const body = rawBody.replace(/\s+/g, ' ');
  const found = [];
  for (const label of LABELS) {
    const idx = body.indexOf(label);
    if (idx !== -1) found.push({ label, start: idx, end: idx + label.length });
  }
  found.sort((a, b) => a.start - b.start);
  const fields = {};
  for (let i = 0; i < found.length; i++) {
    const from = found[i].end;
    const to = i + 1 < found.length ? found[i + 1].start : body.length;
    fields[found[i].label] = body.slice(from, to).trim();
  }
  return fields;
}

// De Gmail Trigger-node geeft, afhankelijk van n8n-versie/instelling, de body
// terug als json.text, json.textPlain of alleen de ruwe payload.parts. Deze
// functie probeert ze op volgorde, zodat de node niet stukgaat op een
// veldnaam-verschil.
function extractBody(json) {
  if (typeof json.text === 'string' && json.text.length > 0) return json.text;
  if (typeof json.textPlain === 'string' && json.textPlain.length > 0) return json.textPlain;
  if (json.payload && json.payload.parts) {
    const stack = [...json.payload.parts];
    while (stack.length) {
      const part = stack.shift();
      if (part.mimeType === 'text/plain' && part.body && part.body.data) {
        const b64 = part.body.data.replace(/-/g, '+').replace(/_/g, '/');
        return Buffer.from(b64, 'base64').toString('utf-8');
      }
      if (part.parts) stack.push(...part.parts);
    }
  }
  return typeof json.snippet === 'string' ? json.snippet : '';
}

function extractSubject(json) {
  if (typeof json.subject === 'string') return json.subject;
  if (json.payload && Array.isArray(json.payload.headers)) {
    const h = json.payload.headers.find((h) => h.name && h.name.toLowerCase() === 'subject');
    if (h) return h.value;
  }
  return '';
}

const results = [];

for (const item of items) {
  const subject = extractSubject(item.json);
  const body = extractBody(item.json);
  const fields = extractFields(body);

  const orderId = fields['OrderID'] || null;
  const txDate = fields['Transactiedatum'] || null;
  const opdracht = fields['Opdracht'] || null;
  const aantal = fields['Aantal'] || null;
  const waarde = fields['Waarde'] || null;

  if (!orderId || !txDate || !opdracht || !aantal || !waarde) {
    results.push({ json: { recognized: false, subject, reason: 'Geen OrderID/Transactiedatum/Opdracht/Aantal/Waarde gevonden in de mail.' } });
    continue;
  }

  const dateMatch = txDate.match(/(\d{1,2}) (\w{3})\w* (\d{4})/);
  const month = dateMatch ? MONTHS[dateMatch[2].toLowerCase()] : null;
  const type = opdracht.toLowerCase().startsWith('koop') ? 'Kopen' : opdracht.toLowerCase().startsWith('verkoop') ? 'Verkopen' : null;
  const quantity = parseInt((aantal || '').replace(/\D/g, ''), 10);
  const waardeMatch = waarde.match(/EUR\s*(-?[\d.,]+)/);

  if (!dateMatch || !month || !type || !quantity || !waardeMatch) {
    results.push({ json: { recognized: false, subject, reason: 'Order-velden gevonden maar niet allemaal leesbaar (datum/type/aantal/waarde).' } });
    continue;
  }

  const date = `${dateMatch[3]}-${month}-${dateMatch[1].padStart(2, '0')}`;
  const waardeEUR = Math.abs(parseFloat(waardeMatch[1].replace(/\./g, '').replace(',', '.')));
  const price = Math.round((waardeEUR / quantity) * 10000) / 10000;
  const nameMatch = subject.match(/^DEGIRO - Transactiebevestiging:\s*(?:Koop|Verkoop)\s*\d+\s*(.+?)\s*@/i);
  const name = nameMatch ? nameMatch[1].trim() : 'Onbekend aandeel';

  results.push({
    json: {
      recognized: true,
      orderId,
      date,
      ticker: deriveTicker(name),
      name,
      type,
      quantity,
      price,
      subject,
    },
  });
}

return results;

